"use client";
import React, { useEffect, useRef, useState } from "react";
import PathContent from "./path-content";
import Icon from "./icon-component";
import { motion, useInView } from "framer-motion";

const LearningPathSection = () => {
  const ref = useRef<SVGSVGElement>(null);
  const sectionRef = useRef<HTMLDivElement>(null);
  const [selectedPath, setSelectedPath] = useState("level1");

  // Use framer-motion's useInView to detect the section visibility
  const isInView = useInView(sectionRef, { once: true, margin: "-50px" });

  useEffect(() => {
    if (ref.current) {
      const pathContent = document.getElementById("path-content");
      // Tìm các path với class path1, path2, path3, path4
      const path1 = ref.current.querySelector(".path1") as SVGPathElement;
      const path2 = ref.current.querySelector(".path2") as SVGPathElement;
      const path3 = ref.current.querySelector(".path3") as SVGPathElement;
      const path4 = ref.current.querySelector(".path4") as SVGPathElement;

      console.log("path1", ref.current);

      //Add class on hover for each path
      path1?.classList.add("cursor-pointer");
      path1?.classList.add("hover:fill-gray-300/50");
      path2?.classList.add("cursor-pointer");
      path2?.classList.add("hover:fill-gray-300/50");
      path3?.classList.add("cursor-pointer");
      path3?.classList.add("hover:fill-gray-300/50");
      path4?.classList.add("cursor-pointer");
      path4?.classList.add("hover:fill-gray-300/50");

      const handleClick1 = () => {
        pathContent?.scrollIntoView({ behavior: "smooth", inline: "nearest" });
        setSelectedPath("level1");
      };
      const handleClick2 = () => {
        pathContent?.scrollIntoView({ behavior: "smooth" });
        setSelectedPath("level2.5");
      };
      const handleClick3 = () => {
        pathContent?.scrollIntoView({ behavior: "smooth" });
        setSelectedPath("level2");
      };
      const handleClick4 = () => {
        pathContent?.scrollIntoView({ behavior: "smooth" });
        setSelectedPath("level3");
      };

      if (path1) path1.addEventListener("click", handleClick1);
      if (path2) path2.addEventListener("click", handleClick2);
      if (path3) path3.addEventListener("click", handleClick3);
      if (path4) path4.addEventListener("click", handleClick4);

      // Cleanup: use correct handler references
      return () => {
        if (path1) path1.removeEventListener("click", handleClick1);
        if (path2) path2.removeEventListener("click", handleClick2);
        if (path3) path3.removeEventListener("click", handleClick3);
        if (path4) path4.removeEventListener("click", handleClick4);
      };
    }
  }, []);

  return (
    <section className="w-full bg-transparent py-12">
      <div className="w-full">
        <motion.div
          ref={sectionRef}
          initial={{ opacity: 0, y: 60 }}
          animate={isInView ? { opacity: 1, y: 0 } : {}}
          transition={{ duration: 0.75, ease: "easeOut" }}
          className="mx-auto flex max-w-7xl flex-col items-center justify-center space-y-6 px-4"
        >
          {/* Title */}
          <motion.h2
            className="mb-1 text-center text-3xl font-bold leading-tight text-slate-700 md:text-4xl lg:text-5xl"
            initial={{ opacity: 0, y: 40 }}
            animate={isInView ? { opacity: 1, y: 0 } : {}}
            transition={{ duration: 0.55, delay: 0.08 }}
          >
            LỘ TRÌNH TRỞ THÀNH KỸ SƯ AI TOÀN NĂNG
          </motion.h2>
          {/* Subtitle/Description */}
          <motion.p
            className="max-w-3xl text-balance text-center text-sm font-medium text-muted-foreground md:text-base"
            initial={{ opacity: 0, y: 32 }}
            animate={isInView ? { opacity: 1, y: 0 } : {}}
            transition={{ duration: 0.62, delay: 0.2 }}
          >
            Theo nghiên cứu, chỉ 5% dân số thế giới có thiên phú phù hợp với
            ngành công nghệ AI, tuy nhiên, kể cả khi bạn có tài năng thiên bẩm,
            con đường bạn đi cũng không hề dễ dàng
            {/* <br /> ( PSG.TS Nguyễn Phi Lê
            - Đại học Bách Khoa Hà Nội Điều hành Viện nghiên cứu trí tuệ nhân
            tạo ) */}
          </motion.p>
        </motion.div>

        {/* SVG Full Width Container */}
        <motion.div
          className="relative w-full overflow-hidden"
          initial={{ opacity: 0, scale: 0.97 }}
          animate={isInView ? { opacity: 1, scale: 1 } : {}}
          transition={{ duration: 0.68, delay: 0.3 }}
        >
          <div className="relative w-full" style={{ paddingBottom: "11.4%" }}>
            <Icon
              icon="roadmapExtend"
              className="absolute inset-0 h-full w-full object-cover"
              ref={ref}
            />
          </div>
        </motion.div>
      </div>

      <motion.div
        id="path-content"
        className="mt-8"
        initial={{ opacity: 0, y: 40 }}
        animate={isInView ? { opacity: 1, y: 0 } : {}}
        transition={{ duration: 0.6, delay: 0.38 }}
      >
        <PathContent selectedPath={selectedPath} />
      </motion.div>
    </section>
  );
};

export default LearningPathSection;
